\set ON_ERROR_STOP on
BEGIN;
CREATE FUNCTION pg_temp.reject_test_archive() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF current_setting('okesih.test_reject_archive',true)='true' AND NEW.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Injected archive failure'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER test_reject_archive BEFORE UPDATE ON public.warkops FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_test_archive();
DO $$
DECLARE w uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); owner_id uuid:=gen_random_uuid(); admin_id uuid:=gen_random_uuid(); cashier_id uuid:=gen_random_uuid(); device uuid:=gen_random_uuid(); shift uuid:=gen_random_uuid(); menu uuid:=gen_random_uuid(); partner uuid:=gen_random_uuid(); billing uuid:=gen_random_uuid(); second_billing uuid:=gen_random_uuid(); other_menu uuid:=gen_random_uuid(); order_id uuid; input jsonb; result jsonb; before_count integer;
BEGIN
 IF has_function_privilege('anon','public.close_waiter_shift(uuid,numeric,text)','EXECUTE') THEN RAISE EXCEPTION 'Public waiter RPC'; END IF;
 IF has_table_privilege('anon','public.warkops','SELECT') THEN RAISE EXCEPTION 'Private profile exposed'; END IF;
 IF has_table_privilege('authenticated','public.transactions','UPDATE') THEN RAISE EXCEPTION 'Browser mutation exposed'; END IF;
 INSERT INTO auth.users(id,raw_app_meta_data) VALUES(owner_id,'{}'),(admin_id,'{"role":"SUPERADMIN"}');
 INSERT INTO public.marketing_partners(id,full_name,phone,city_area,referral_code,bank_account_number,bank_account_name,status) VALUES(partner,'Test','0','Test','test-'||partner,'0','Test','ACTIVE');
 INSERT INTO public.warkops(id,nama,slug,marketing_agent_id) VALUES(w,'Test','test-'||w,partner),(other,'Other','test-'||other,NULL);
 INSERT INTO public.warkop_members(warkop_id,user_id,username,role) VALUES(w,owner_id,'owner','OWNER');
 PERFORM public.set_tenant_audit_pin(w,'1234',owner_id);
 IF NOT public.verify_tenant_audit_pin(w,'1234') OR public.verify_tenant_audit_pin(w,'9999') THEN RAISE EXCEPTION 'PIN validation failed'; END IF;
 IF (SELECT pin_hash FROM public.tenant_audit_pins WHERE warkop_id=w)='1234' THEN RAISE EXCEPTION 'Plaintext PIN'; END IF;
 IF NOT (public.consume_api_limit('test',1,60)->>'allowed')::boolean OR (public.consume_api_limit('test',1,60)->>'allowed')::boolean THEN RAISE EXCEPTION 'Rate limit failed'; END IF;
 INSERT INTO public.warkop_members(id,warkop_id,username,role) VALUES(cashier_id,w,'cashier','KASIR');
 INSERT INTO public.device_installations(id,warkop_id,device_type,device_name,token_hash,expires_at) VALUES(device,w,'POS','Test',repeat('a',64),now()+interval '1 day');
 INSERT INTO public.shifts(id,warkop_id,opened_by,device_id) VALUES(shift,w,cashier_id,device);
 INSERT INTO public.warkop_tables(warkop_id,label) VALUES(w,'1');
 INSERT INTO public.menus(id,warkop_id,nama,harga,kategori) VALUES(menu,w,'Coffee',10000,'Drink');
 input:=jsonb_build_object('idempotencyKey',gen_random_uuid(),'tableNumber','1','paymentMethod','CASH','items',jsonb_build_array(jsonb_build_object('menuId',menu,'qty',2)));
 result:=public.create_order_v2(w,input,'hash','token'); order_id:=(result->>'id')::uuid;
 IF result->>'status_pesanan'<>'AWAITING_CONFIRMATION' OR (result->>'total')::numeric<>20000 THEN RAISE EXCEPTION 'Public order invalid'; END IF;
 IF (public.create_order_v2(w,input,'hash','token')->>'id')::uuid<>order_id THEN RAISE EXCEPTION 'Replay duplicated'; END IF;
 BEGIN PERFORM public.create_order_v2(w,input,'other-hash','token'); RAISE EXCEPTION 'Expected hash conflict' USING ERRCODE='XX000'; EXCEPTION WHEN raise_exception THEN NULL; END;
 IF (public.report_transaction_summary(w)->>'total')::numeric<>0 THEN RAISE EXCEPTION 'Pending counted as revenue'; END IF;
 IF (SELECT count(*) FROM public.transactions WHERE warkop_id=w)<>1 THEN RAISE EXCEPTION 'Duplicate transaction'; END IF;
 input:=jsonb_build_object('idempotencyKey',gen_random_uuid(),'orderId',order_id,'status','COOKING','shiftId',shift);
 PERFORM public.transition_order_v2(w,device,cashier_id,input,'transition');
 PERFORM public.transition_order_v2(w,device,cashier_id,input,'transition');
 IF (SELECT count(*) FROM public.operation_idempotency WHERE warkop_id=w)<>1 THEN RAISE EXCEPTION 'Duplicate transition'; END IF;
 IF (public.report_transaction_summary(w)->>'total')::numeric<>20000 THEN RAISE EXCEPTION 'Confirmed revenue missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.transactions WHERE id=order_id AND confirmed_at IS NOT NULL AND shift_id=shift AND status_pesanan='COOKING') THEN RAISE EXCEPTION 'Confirmation missing'; END IF;
 INSERT INTO public.menus(id,warkop_id,nama,harga,kategori) VALUES(other_menu,other,'Other',100,'Drink');
 BEGIN UPDATE public.transaction_items SET menu_id=other_menu WHERE transaction_id=order_id; RAISE EXCEPTION 'Expected tenant constraint' USING ERRCODE='XX000'; EXCEPTION WHEN foreign_key_violation THEN NULL; END;
 INSERT INTO public.saas_billings(id,warkop_id,tanggal,total_transactions,tagihan_pokok,kode_unik,total_tagihan,shift_id) VALUES(billing,w,current_date,2,200,123,323,shift);
 PERFORM public.submit_billing_proof(billing,w,owner_id,'saas-billings/'||w||'/test.png',repeat('b',64),'OCR says paid');
 IF (SELECT status_bayar FROM public.saas_billings WHERE id=billing)<>'PENDING_REVIEW' THEN RAISE EXCEPTION 'Upload settled'; END IF;
 BEGIN PERFORM public.review_billing(billing,owner_id,'APPROVE','test-ref',''); RAISE EXCEPTION 'Expected role denial' USING ERRCODE='XX000'; EXCEPTION WHEN raise_exception THEN NULL; END;
 PERFORM public.review_billing(billing,admin_id,'APPROVE','test-ref-'||billing,'');
 SELECT count(*) INTO before_count FROM public.marketing_commission_mutations WHERE billing_id=billing;
 IF before_count<>1 THEN RAISE EXCEPTION 'Commission missing'; END IF;
 PERFORM public.review_billing(billing,admin_id,'APPROVE','test-ref-'||billing,'');
 IF (SELECT count(*) FROM public.marketing_commission_mutations WHERE billing_id=billing)<>before_count THEN RAISE EXCEPTION 'Duplicate commission'; END IF;
 BEGIN DELETE FROM public.saas_billings WHERE id=billing; RAISE EXCEPTION 'Expected immutable billing' USING ERRCODE='XX000'; EXCEPTION WHEN check_violation THEN NULL; END;
 INSERT INTO public.saas_billings(id,warkop_id,tanggal,total_transactions,tagihan_pokok,kode_unik,total_tagihan) VALUES(second_billing,w,current_date,1,100,100,200);
 IF (public.report_daily_billing(w,current_date)->>'total_tagihan')::numeric<>523 THEN RAISE EXCEPTION 'Daily billing aggregation failed'; END IF;
 UPDATE public.saas_billings SET proof_uploaded_at=now()-interval '91 days' WHERE id=billing;
 PERFORM public.enqueue_expired_billing_proofs();
 IF (SELECT bukti_transfer_url FROM public.saas_billings WHERE id=billing) IS NOT NULL THEN RAISE EXCEPTION 'Retention failed'; END IF;
 BEGIN PERFORM public.delete_entity_permanently('TENANT',w,admin_id); RAISE EXCEPTION 'Finance deletion allowed' USING ERRCODE='XX000'; EXCEPTION WHEN check_violation THEN NULL; END;
 IF NOT EXISTS(SELECT FROM public.transactions WHERE id=order_id) OR NOT EXISTS(SELECT FROM public.saas_billings WHERE id=billing) OR NOT EXISTS(SELECT FROM public.marketing_commission_mutations WHERE billing_id=billing) THEN RAISE EXCEPTION 'Financial history lost'; END IF;
 RAISE NOTICE 'PASS: ACL, order replay/conflict, confirmation, cross-tenant FK, manual billing, commission replay, immutable ledger, financial retention';
END $$;
ROLLBACK;
